#!/usr/bin/env node

/*
 * Generate the Cobb night-hike almanac.
 *
 * A "good night hiking event" is a night when either:
 *   1. a big moon (within N days of full) is above the horizon at some moment
 *      between sunset and the evening cutoff, or
 *   2. moonrise happens between sunset and the evening cutoff.
 *
 * The output is a small JSON file that the browser reads. It is regenerated by
 * GitHub Actions before the Jekyll build, and can also be run by hand:
 *
 *   node scripts/night-hikes/generate.mjs
 *   node scripts/night-hikes/generate.mjs --start=2026-11-10 --days=90
 *
 * All dates and times in the output are UTC instants, but the dates chosen are
 * Cobb local calendar dates and the browser formats every instant in Cobb
 * local time.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  createObserver,
  fullMoonsBetween,
  moonAltitude,
  moonIllumination,
  moonriseOn,
  moonsetOn,
  sunsetOn,
} from './sky.mjs';
import { addDays, dayDifference, localDateString, parseClock, zonedTimeToUtc } from './time.mjs';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const defaultConfigPath = path.resolve(scriptDir, '../night-hikes.config.json');
const defaultOutputPath = path.resolve(scriptDir, '../../assets/data/night-hikes.json');

function usage() {
  return [
    'Usage: node scripts/night-hikes/generate.mjs [options]',
    '',
    'Options:',
    '  --start=YYYY-MM-DD  First local date to include (default: today in Cobb)',
    '  --days=N            Number of local dates to cover (default: config forecastDays)',
    '  --out=PATH          Output JSON path (default: assets/data/night-hikes.json)',
    '  --help              Show this help',
  ].join('\n');
}

function parseArgs(argv) {
  const args = {};

  for (const arg of argv) {
    if (arg === '--help' || arg === '-h') {
      args.help = true;
      continue;
    }

    const match = /^--(start|days|out)=(.*)$/.exec(arg);

    if (!match) {
      throw new Error(`Unknown argument "${arg}".\n\n${usage()}`);
    }

    args[match[1]] = match[2];
  }

  return args;
}

function readConfig(configPath) {
  const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

  if (!config.location || typeof config.location !== 'object') {
    throw new Error('Config is missing a location object.');
  }

  const { latitude, longitude, timezone } = config.location;

  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
    throw new Error('Config location.latitude and location.longitude must be numbers.');
  }

  if (typeof timezone !== 'string' || timezone.length === 0) {
    throw new Error('Config location.timezone must be an IANA timezone name.');
  }

  if (!Number.isInteger(config.forecastDays) || config.forecastDays < 1) {
    throw new Error('Config forecastDays must be a positive integer.');
  }

  if (!Number.isInteger(config.fullMoonWindowDays) || config.fullMoonWindowDays < 0) {
    throw new Error('Config fullMoonWindowDays must be a non-negative integer.');
  }

  parseClock(config.eveningEnd);

  const visible = config.visibleAboveHorizon;

  if (!visible || !Number.isFinite(visible.minAltitudeDegrees)) {
    throw new Error('Config visibleAboveHorizon.minAltitudeDegrees must be a number.');
  }

  if (!Number.isInteger(visible.sampleMinutes) || visible.sampleMinutes < 1) {
    throw new Error('Config visibleAboveHorizon.sampleMinutes must be a positive integer.');
  }

  return config;
}

function round(value, places = 1) {
  const factor = 10 ** places;

  return Math.round(value * factor) / factor;
}

function iso(timestamp) {
  return new Date(timestamp).toISOString();
}

// Almanacs round to the nearest minute; Intl drops seconds. Shift forward
// half a minute so the log agrees with the page.
const HALF_MINUTE_MS = 30 * 1000;

function rounded(date) {
  return new Date(date.getTime() + HALF_MINUTE_MS);
}

function formatLocalDateTime(date, timeZone) {
  return new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    timeZoneName: 'short',
  }).format(rounded(date));
}

function formatLocalTime(date, timeZone) {
  return new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: 'numeric',
    minute: '2-digit',
  }).format(rounded(date));
}

function nearestFullMoon(date, fullMoons, timeZone) {
  let best = null;

  for (const fullMoon of fullMoons) {
    const localDate = localDateString(fullMoon, timeZone);
    const difference = dayDifference(date, localDate);

    if (best === null || Math.abs(difference) < Math.abs(best.daysFromFullMoon)) {
      best = {
        instant: fullMoon,
        localDate,
        daysFromFullMoon: difference,
      };
    }
  }

  return best;
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) {
    console.log(usage());
    return;
  }

  const config = readConfig(defaultConfigPath);
  const { latitude, longitude, timezone } = config.location;
  const startDate = args.start || localDateString(new Date(), timezone);
  const days = args.days ? Number.parseInt(args.days, 10) : config.forecastDays;
  const outputPath = args.out ? path.resolve(args.out) : defaultOutputPath;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
    throw new Error(`Invalid --start value "${startDate}"; expected YYYY-MM-DD.`);
  }

  if (!Number.isInteger(days) || days < 1) {
    throw new Error(`Invalid --days value "${args.days}"; expected a positive integer.`);
  }

  const endDate = addDays(startDate, days - 1);
  const eveningEnd = parseClock(config.eveningEnd);
  const windowDays = config.fullMoonWindowDays;
  const minAltitude = config.visibleAboveHorizon.minAltitudeDegrees;
  const sampleMs = config.visibleAboveHorizon.sampleMinutes * 60 * 1000;

  // Search a little beyond the forecast range so nights near the edges still
  // know which full moon is closest.
  const fullMoonSearchStart = zonedTimeToUtc(
    addDays(startDate, -windowDays - 2),
    0,
    0,
    timezone,
  ).getTime();
  const fullMoonSearchEnd = zonedTimeToUtc(
    addDays(endDate, windowDays + 2),
    0,
    0,
    timezone,
  ).getTime();
  const fullMoons = fullMoonsBetween(fullMoonSearchStart, fullMoonSearchEnd);
  const observer = createObserver(config.location);

  const events = [];
  let skippedSunsets = 0;

  for (let index = 0; index < days; index += 1) {
    const date = addDays(startDate, index);
    const sunset = sunsetOn(date, timezone, observer);

    if (sunset === null) {
      skippedSunsets += 1;
      continue;
    }

    const sunsetMs = sunset.getTime();
    const windowEndMs = zonedTimeToUtc(
      date,
      eveningEnd.hour,
      eveningEnd.minute,
      timezone,
    ).getTime();

    if (windowEndMs <= sunsetMs) {
      continue;
    }

    const moonrise = moonriseOn(date, timezone, observer);
    const moonset = moonsetOn(date, timezone, observer);
    const moonriseMs = moonrise === null ? null : moonrise.getTime();
    const moonsetMs = moonset === null ? null : moonset.getTime();

    const altitudeAtSunset = moonAltitude(new Date(sunsetMs), observer);
    const altitudeAtWindowEnd = moonAltitude(new Date(windowEndMs), observer);
    const aboveAtSunset = altitudeAtSunset >= minAltitude;
    const aboveAtWindowEnd = altitudeAtWindowEnd >= minAltitude;

    let firstAbove = null;
    let lastAbove = null;
    let maxAltitude = -Infinity;

    for (let ms = sunsetMs; ms <= windowEndMs; ms += sampleMs) {
      const altitude = moonAltitude(new Date(ms), observer);

      if (altitude >= minAltitude) {
        if (firstAbove === null) {
          firstAbove = ms;
        }

        lastAbove = ms;
      }

      if (altitude > maxAltitude) {
        maxAltitude = altitude;
      }
    }

    // Make sure the very end of the window is sampled even when the interval
    // does not divide evenly into 60 seconds.
    const finalAltitude = moonAltitude(new Date(windowEndMs), observer);

    if (finalAltitude >= minAltitude) {
      if (firstAbove === null) {
        firstAbove = windowEndMs;
      }

      lastAbove = windowEndMs;
    }

    if (finalAltitude > maxAltitude) {
      maxAltitude = finalAltitude;
    }

    const moonriseInWindow =
      moonriseMs !== null && moonriseMs >= sunsetMs && moonriseMs <= windowEndMs;
    const moonsetInWindow = moonsetMs !== null && moonsetMs >= sunsetMs && moonsetMs <= windowEndMs;

    const moonVisible = firstAbove !== null;
    const visibleFrom = aboveAtSunset ? sunsetMs : firstAbove;
    const visibleUntil = aboveAtWindowEnd ? windowEndMs : lastAbove;

    const fullMoon = nearestFullMoon(date, fullMoons, timezone);
    const isBigMoon = fullMoon !== null && Math.abs(fullMoon.daysFromFullMoon) <= windowDays;
    const qualified = (isBigMoon && moonVisible) || moonriseInWindow;

    if (!qualified) {
      continue;
    }

    const reasons = [];

    if (isBigMoon) {
      reasons.push('big-moon');
    }

    if (moonriseInWindow) {
      reasons.push('moonrise');
    }

    const illumination = moonIllumination(new Date((sunsetMs + windowEndMs) / 2));

    events.push({
      date,
      sunset: iso(sunsetMs),
      windowEnd: iso(windowEndMs),
      moonrise: moonriseMs === null ? null : iso(moonriseMs),
      moonset: moonsetMs === null ? null : iso(moonsetMs),
      moonVisible,
      moonVisibleFrom: visibleFrom === null ? null : iso(visibleFrom),
      moonVisibleUntil: visibleUntil === null ? null : iso(visibleUntil),
      moonAltitudeAtSunset: round(altitudeAtSunset),
      moonAltitudeAtWindowEnd: round(altitudeAtWindowEnd),
      moonAltitudeMax: round(maxAltitude),
      moonIllumination: round(illumination, 3),
      fullMoon:
        fullMoon === null
          ? null
          : {
              instant: iso(fullMoon.instant),
              localDate: fullMoon.localDate,
              daysFromFullMoon: fullMoon.daysFromFullMoon,
            },
      isBigMoon,
      moonriseInWindow,
      reasons,
    });
  }

  const output = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    generator: 'scripts/night-hikes/generate.mjs',
    location: {
      name: config.location.name,
      latitude,
      longitude,
      elevationMeters: config.location.elevationMeters,
      timezone,
    },
    config: {
      forecastDays: days,
      eveningEnd: config.eveningEnd,
      fullMoonWindowDays: windowDays,
      visibleAboveHorizon: {
        minAltitudeDegrees: minAltitude,
        sampleMinutes: config.visibleAboveHorizon.sampleMinutes,
      },
    },
    range: {
      start: startDate,
      end: endDate,
    },
    events,
  };

  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, `${JSON.stringify(output, null, 2)}\n`, 'utf8');

  console.log(`Night-hike almanac: ${startDate} through ${endDate} (${days} days)`);
  console.log(`Location: ${config.location.name} (${latitude}, ${longitude})`);
  console.log(`Full moons in search range: ${fullMoons.length}`);

  if (skippedSunsets > 0) {
    console.warn(`Skipped ${skippedSunsets} day(s) with no sunset crossing.`);
  }

  console.log(`Qualifying nights: ${events.length}`);

  for (const event of events.slice(0, 5)) {
    const reasons = event.reasons.join(' + ');
    console.log(
      `  ${event.date}: ${reasons}; sunset ${formatLocalTime(new Date(event.sunset), timezone)}, window ends ${formatLocalTime(new Date(event.windowEnd), timezone)}`,
    );
  }

  console.log(`Wrote ${outputPath}`);
  console.log(`Generated at ${formatLocalDateTime(new Date(output.generatedAt), timezone)}`);
}

try {
  main();
} catch (error) {
  console.error(`night-hike generator: ${error.message}`);
  process.exitCode = 1;
}
